const origin = String(env.get("RAYWN2_API_URL") || "").replace(/\/$/, "");
const token = String(env.get("RAYWN2_API_TOKEN") || "");
const device = String(env.get("RAYWN2_API_DEVICE") || "");
const channel = Number(env.get("RAYWN2_API_CHANNEL") || "2");
if (!/^https:\/\/[^\s\/?#@]+$/.test(origin) || !/^[a-f0-9]{64}$/.test(token) || !device || !Number.isInteger(channel) || channel < 1 || channel > 4) {
    node.status({fill:"yellow",shape:"ring",text:"Configure API URL, token, device and channel"});
    return null;
}
msg.url = origin + "/api/v1/readings?device=" + encodeURIComponent(device);
msg.method = "GET";
msg.headers = {Authorization:"Bearer " + token, Accept:"application/json"};
msg.requestTimeout = 5000;
msg.followRedirects = false;
msg.rejectUnauthorized = true;
return msg;

// Return a NEW message: never send request headers, URL or token to Debug/UI.
const device = String(env.get("RAYWN2_API_DEVICE") || "");
const channel = Number(env.get("RAYWN2_API_CHANNEL") || "2");
const empty = {device,channel,available:false,status:"Unavailable / stale",forward_average_W:null,forward_peak_W:null,reflected_average_W:null,reflected_peak_W:null,swr:null};
const body = msg.payload;
const d = Number(msg.statusCode) === 200 && body && body.schema === 1 && Array.isArray(body.devices) ? body.devices.find(x=>x.device === device) : null;
const rf = d && Array.isArray(d.rf) ? d.rf.find(x=>x.channel === channel) : null;
if (!d || d.fresh !== true || !Number.isFinite(d.age_ms) || d.age_ms < 0 || d.age_ms >= 1500 || !rf) {
    flow.set("rayApiExpiry",0);
    node.status({fill:"yellow",shape:"ring",text:empty.status});
    return {payload:empty};
}
flow.set("rayApiExpiry",Date.now() + 1500 - d.age_ms);
const result = {...empty,available:true,status:rf.status,received_utc:d.received_utc,source:d.source,transport:d.transport};
for (const key of ["forward_average_W","forward_peak_W","reflected_average_W","reflected_peak_W","swr"]) result[key] = Number.isFinite(rf[key]) ? rf[key] : null;
node.status({fill:"green",shape:"dot",text:"Fresh " + device + " CH" + channel});
return {payload:result};
